/* ============================================================
   训练日记 · app.js
   居家哑铃训练记录 App：常驻浮层桌宠 + 训练 / 饮食 / 数据 / 助手四个模块。

   设计约束（改动前请先读）：
   - 纯前端单页，无构建、无框架、无后端；数据只存本机 localStorage（键 boji_v7）。
   - 桌宠形象、教练身份、桌面背景全部可更换，切换只换渲染数据源，不动用户数据。
   - 训练计划分 A / B 两套（有 / 无卧推椅），两套数据各自完整、互不交叉引用。
   - 所有写入走 save()：存储不可用时返回 false 并提示，绝不静默丢数据。
   - 识别能力：未配置 AI 时明确降级为条码 / 在线库 / 历史 / 本地匹配，不返回编造结果。

   历史版本流水见 docs/轮次总结.md，此处不再罗列。
   ============================================================ */
'use strict';
const APP_VERSION = '1.2.0';   // 语义化版本 MAJOR.MINOR.PATCH；发布规范见 docs/产品评估与开源差距清单.md
const $ = s => document.querySelector(s);
const $$ = s => Array.from(document.querySelectorAll(s));
const el = html => { const t = document.createElement('template'); t.innerHTML = html.trim(); return t.content.firstChild; };
// 加 String() 兜底——旧版传入非字符串（null/undefined/对象）会抛 s.replace is not a function
const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' }[c]));
const DEFAULT_COACH = '小练';
// 教练身份：名字与头像可更换（预设三只连帽衫小狗形象 + 自定义上传），全局生效
function coachName(){
  const s = STATE && STATE.settings;
  const n = s && typeof s.coachName === 'string' ? s.coachName.trim() : '';
  return n ? n.slice(0, 10) : DEFAULT_COACH;
}
function coachAvatarSrc(){
  const a = STATE && STATE.settings && STATE.settings.coachAvatar;
  if(a && a.slice(0, 5) === 'data:') return a;
  // 修复：COACH_AV_SVG 里存的是 SVG 标记字符串，旧版直接塞进 <img src> 必然渲染成破图
  if(a && COACH_AV_SVG[a]) return svgURI(COACH_AV_SVG[a]);
  return svgURI(COACH_AV_SVG.dog2);
}
const svgURI = s => 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(String(s == null ? '' : s));

/* ---------- 视频深链（卓叔 B站合集，章节时间戳可点开自验） ---------- */
/* v1.1：B 站单视频直链（每个动作唯一对应一个视频，label 用真实视频标题，便于核对）。
   来源：B 站搜索结果，按「标题必须含该动作核心名词 + 教学信号」筛选，见 docs/视频来源核对.md */
const blink = (bvid, label) => ({ url: 'https://www.bilibili.com/video/' + bvid, label });
const TIMESTAMP_NOTE = '时间戳取自卓叔《30个家庭哑铃增肌动作教学》合集章节，属最佳可得映射，点开可自验。';

/* ---------- 训练计划：两套独立方案（A 有卧推椅 / B 无卧推椅）----------
   两套均覆盖 推 / 拉 / 腿 / 核心 四大肌群，各 4 训练日 × 6 动作 = 24 个动作；
   两套数据各自完整、互不交叉引用（切换方案只换数据源，不共享动作对象）。

   动作字段格式（两套统一）：
     name     动作名
     muscle   目标肌群
     sets     组数
     reps     每组次数（支撑类等长动作为秒数）
     tempo    动作节奏「离心-底停-向心」秒数，如 2-1-1；等长动作写「静态」
     breath   呼吸方式
     rest     组间休息（秒）
     base     起始建议重量系数（× 单只哑铃重量，见 suggKg）；自重动作为 0
     video    教学视频（卓叔合集时间戳；合集未收录的用站内搜索兜底，不伪造时间戳）
     standard 动作标准
     note     常见错误提示 */
const bsearch = kw => ({ url: 'https://search.bilibili.com/all?keyword=' + encodeURIComponent(kw), label: kw + '（合集外·站内搜）' });
